const inputData = $input.item.json || {};
const textoSalida = valor => {
  if (valor === null || valor === undefined) return '';
  if (typeof valor === 'string' || typeof valor === 'number' || typeof valor === 'boolean') {
    return valor.toString();
  }
  if (Array.isArray(valor)) {
    return valor.map(textoSalida).filter(Boolean).join('\n');
  }
  if (typeof valor === 'object') {
    return textoSalida(valor.output || valor.text || valor.response || valor.result || valor.answer || valor.content || valor.message);
  }
  return '';
};
const extraerSalidaAgente = data => {
  const candidatos = [
    data.output,
    data.text,
    data.response,
    data.result,
    data.answer,
    data.message?.content,
    data.chatMessage?.content,
    data.generations?.[0]?.[0]?.text
  ];
  return candidatos.map(textoSalida).find(valor => valor.trim() !== '')?.trim() || '';
};
const output = extraerSalidaAgente(inputData);
const jsonMatch = output.match(/\{[\s\S]*?"accion"[\s\S]*?\}/);

// Toda la configuracion viene de Supabase (tablas clinicas + tratamientos).
const CFG = $('Construir contexto').first().json.config;
const TIME_ZONE = CFG.zona_horaria;
const DURACION_CITA_MIN = CFG.duracion_por_defecto;
const DURACIONES_TRATAMIENTO = CFG.duraciones;

const trigger = $('WhatsApp Trigger').first().json;
const telefono = trigger.messages?.[0]?.from || '';
const mensajeActual = trigger.messages?.[0]?.text?.body || '';

const normalizarTexto = texto => (texto || '')
  .toString()
  .toLowerCase()
  .normalize('NFD')
  .replace(/[\u0300-\u036f]/g, '')
  .replace(/\s+/g, ' ')
  .trim();

const datoVacio = valor => valor === null || valor === undefined || valor.toString().trim() === '';

const duracionTratamiento = tratamiento => {
  const valor = normalizarTexto(tratamiento);
  const encontrado = DURACIONES_TRATAMIENTO.find(item =>
    item.patrones.some(patron => valor.includes(normalizarTexto(patron)))
  );
  return encontrado ? encontrado.minutos : DURACION_CITA_MIN;
};


const mensajeActualNormalizado = normalizarTexto(mensajeActual);
const contieneTratamiento = texto => {
  const valor = normalizarTexto(texto);
  return DURACIONES_TRATAMIENTO.some(item =>
    item.patrones.some(patron => valor.includes(normalizarTexto(patron)))
  );
};
const esConsultaExplicitaHorarios = texto => /\b(horarios?|disponibilidad|disponibles?|huecos?|libres?|que horas|horas hay|agenda)\b/.test(normalizarTexto(texto));
const esRespuestaCortaTratamiento = texto => {
  const limpio = normalizarTexto(texto)
    .replace(/^(?:(?:para|por|de|del|una|un|la|el)\s+)+/, '')
    .trim();
  const palabras = limpio.split(/\s+/).filter(Boolean);
  return palabras.length > 0
    && palabras.length <= 5
    && contieneTratamiento(limpio)
    && !esConsultaExplicitaHorarios(limpio)
    && !/\b(cancelar|cambiar|modificar|mover|reprogramar|precio|cuanto|cuesta|coste)\b/.test(limpio);
};

const esMensajeSeleccionHora = texto => {
  const limpio = normalizarTexto(texto);
  return /(?:^|\b)(?:a\s*)?(?:las?|los)?\s*\d{1,2}(?::\d{2})?\s*(?:am|pm)?(?:\b|$)/.test(limpio)
    && !contieneTratamiento(limpio)
    && !esConsultaExplicitaHorarios(limpio)
    && !/\b(me llamo|soy|nombre|cancelar|cambiar|modificar|mover|reprogramar)\b/.test(limpio);
};

const nombrePareceEjemploPrompt = nombre => {
  const valor = normalizarTexto(nombre);
  return ['x', 'xx', 'xxx', 'nombre'].includes(valor)
    || valor.includes('nombre real')
    || valor.includes('nombre en memoria')
    || valor.includes('nombre del cliente')
    || valor.includes('nombre del paciente')
    || valor.includes('nombre_de_paciente')
    || valor.includes('nombre_del_paciente')
    || valor.includes('tu nombre completo')
    || valor.includes('[')
    || valor.includes(']');
};
const tratamientoGenerico = tratamiento => {
  const valor = normalizarTexto(tratamiento);
  return valor === 'cita' || valor.startsWith('cita est');
};
const tratamientoPareceEjemploPrompt = tratamiento => {
  const valor = normalizarTexto(tratamiento);
  return valor.includes('tratamiento real')
    || valor.includes('tratamiento en memoria')
    || valor.includes('[')
    || valor.includes(']');
};

const responder = texto => [{
  json: {
    accion: 'responder',
    es_reserva: false,
    es_cancelacion: false,
    es_modificacion: false,
    telefono,
    respuesta: texto
  }
}];

const esSaludoSimple = texto => /^(hola|buenas|buenos dias|buenas tardes|buenas noches|hey|hi|hello|ola|oi|bonjour|bonsoir|kaixo|epa)\b/.test(texto);
const preguntaIdentidad = texto => /\b(sabes quien soy|sabes quien soy\?|quien soy|me conoces|sabes mi nombre)\b/.test(texto);

const limitarTexto = (texto, max = 900) => {
  const valor = (texto || '').toString().replace(/\s+/g, ' ').trim();
  if (valor.length <= max) return valor;
  return valor.slice(0, max - 3).trim() + '...';
};

const limpiarNombreExtraido = valor => {
  const inicial = limitarTexto(valor, 160)
    .replace(/\s+/g, ' ')
    .replace(/^[,.;:!?\s]+|[,.;:!?\s]+$/g, '')
    .trim();
  const cortado = inicial
    .split(/\s+\b(?:porque|por que|no se|tengo|me duele|me sangra|sangra|ademas|cuando)\b/i)[0]
    .replace(/^[,.;:!?\s]+|[,.;:!?\s]+$/g, '')
    .trim();
  const palabras = cortado.split(/\s+/).filter(Boolean);
  if (palabras.length < 2 || palabras.length > 6) return '';
  if (/\d|\b(cita|revision|limpieza|blanqueamiento|empaste|ortodoncia|dolor|sangrado|muela|diente)\b/i.test(cortado)) return '';
  return nombrePareceEjemploPrompt(cortado) ? '' : cortado;
};

const extraerNombreMensaje = texto => {
  const raw = (texto || '').toString().replace(/\s+/g, ' ').trim();
  if (!raw) return '';
  const patrones = [
    /\b(?:a|al|en)\s+nombre\s+de\s+(.+?)(?=[,.;:!?]|$)/i,
    /\bnombre\s*[:=]\s*(.+?)(?=[,.;:!?]|$)/i,
    /\bme\s+llamo\s+(.+?)(?=[,.;:!?]|$)/i,
    /\bsoy\s+(.+?)(?=[,.;:!?]|$)/i
  ];
  for (const patron of patrones) {
    const match = raw.match(patron);
    const nombre = match ? limpiarNombreExtraido(match[1]) : '';
    if (nombre) return nombre;
  }
  return '';
};

const contieneInfoClinicaPrivada = texto => {
  const valor = normalizarTexto(texto);
  if (!valor) return false;
  const terminos = [
    'me duele', 'duele', 'dolor', 'molestia', 'sensibilidad', 'punzada', 'latido', 'ardor',
    'sangra', 'sangrado', 'sangre', 'hemorragia', 'pus', 'supura', 'absceso', 'flemon', 'infeccion', 'infectado', 'infectada',
    'inflamado', 'inflamada', 'hinchado', 'hinchada', 'hinchazon', 'bulto', 'llaga', 'herida', 'ulcera', 'fiebre',
    'diente roto', 'muela rota', 'se me cayo', 'se me ha caido', 'golpe', 'accidente', 'trauma', 'caries',
    'embarazada', 'embarazo', 'lactancia', 'alergia', 'alergico', 'diabetes', 'cardiaco', 'anticoagulante', 'medicacion', 'medicamento', 'antibiotico', 'tomo ',
    'pain', 'hurt', 'hurts', 'bleeding', 'blood', 'swollen', 'swelling', 'infection', 'abscess', 'fever', 'broken tooth', 'pregnant', 'allergy', 'medication',
    'dor', 'doi', 'doendo', 'sangramento', 'inchado', 'inchada', 'infeccao', 'infecao', 'febre', 'abscesso', 'gravida', 'medicamento',
    'douleur', 'mal aux', 'saigne', 'saignement', 'gonfle', 'fievre', 'abces', 'enceinte', 'allergie', 'medicament'
  ];
  if (terminos.some(termino => valor.includes(termino))) return true;
  const patrones = [
    /\b(caries|encia|muelas?|dientes?|mandibula|bruxismo)\b.*\b(dolor|duele|sangra|hinchad[oa]|roto|rota|pus|infeccion)\b/,
    /\b(dolor|duele|sangra|hinchad[oa]|roto|rota|pus|infeccion)\b.*\b(caries|encia|muelas?|dientes?|mandibula|bruxismo)\b/
  ];
  return patrones.some(patron => patron.test(valor));
};

const datosDerivacionHumano = (data = {}) => {
  const nombreCandidato = data.nombre || data.paciente || extraerNombreMensaje(mensajeActual) || '';
  const nombre = !datoVacio(nombreCandidato) && !nombrePareceEjemploPrompt(nombreCandidato)
    ? limitarTexto(nombreCandidato, 120)
    : '';
  const motivo = limitarTexto(data.motivo || data.motivo_derivacion || 'consulta clinica privada', 180);
  const resumen = limitarTexto(
    data.resumen || data.resumen_derivacion || data.comentario || mensajeActual || 'El paciente solicita atencion humana.',
    900
  );
  const derivacionId = data.derivacion_id || ('DH-' + [telefono || 'sin-telefono', Date.now().toString(36)]
    .join('-')
    .replace(/[^a-z0-9-]/gi, '')
    .slice(0, 90));
  const derivadoEn = data.derivado_en || new Intl.DateTimeFormat('es-ES', {
    timeZone: TIME_ZONE,
    day: '2-digit',
    month: '2-digit',
    year: 'numeric',
    hour: '2-digit',
    minute: '2-digit',
    hour12: false
  }).format(new Date()).replace(',', '');
  const respuestaDerivacion = 'Gracias por contarnoslo. Paso tu mensaje a una persona de la clinica para que lo revise. Si prefieres hablar directamente, puedes llamar al ' + CFG.telefono_publico + ' en horario de la clinica.';

  return {
    es_derivacion_humano: true,
    requiere_derivacion_humano: true,
    derivacion_id: derivacionId,
    derivado_en: derivadoEn,
    nombre,
    motivo_derivacion: motivo,
    resumen_derivacion: resumen,
    mensaje_original: limitarTexto(mensajeActual, 1200),
    respuesta_derivacion: respuestaDerivacion
  };
};

const crearDerivacionHumano = (data = {}) => {
  const derivacion = datosDerivacionHumano(data);
  return [{
    json: {
      accion: 'derivar_humano',
      es_reserva: false,
      es_cancelacion: false,
      es_modificacion: false,
      telefono,
      ...derivacion,
      respuesta: derivacion.respuesta_derivacion
    }
  }];
};

if (!output) {
  if (contieneInfoClinicaPrivada(mensajeActual)) {
    return crearDerivacionHumano({});
  }
  if (preguntaIdentidad(mensajeActualNormalizado)) {
    return responder('Por privacidad no puedo identificarte solo por el chat. Si quieres gestionar una cita, dime tu nombre completo y te ayudo encantada.');
  }
  if (esSaludoSimple(mensajeActualNormalizado)) {
    return responder('Hola, soy ' + CFG.nombre_asistente + ' de ' + CFG.nombre + '. En que puedo ayudarte?');
  }
  if (/\b(cita|reservar|reserva|agendar|pedir hora|appointment|marcar consulta)\b/.test(mensajeActualNormalizado)) {
    return responder('Claro. Me dices tu nombre completo para empezar con la reserva?');
  }
}

const normHora = h => {
  if (h === null || h === undefined || h === '') return '';
  if (typeof h === 'number') {
    let totalMin;
    if (h >= 0 && h < 1) {
      totalMin = Math.round(h * 24 * 60);
    } else {
      const horas = Math.floor(h);
      const minutos = Math.round((h - horas) * 60);
      totalMin = horas * 60 + minutos;
    }
    const hh = Math.floor(totalMin / 60).toString().padStart(2, '0');
    const mm = (totalMin % 60).toString().padStart(2, '0');
    return hh + ':' + mm;
  }

  let v = h.toString().trim().toLowerCase();
  v = v.replace(/\s*(horas|hora|hrs?|h)\s*$/i, '').trim();
  v = v.replace('.', ':');

  const ampm = v.match(/^(\d{1,2})(?::(\d{1,2}))?\s*(am|pm)$/i);
  if (ampm) {
    let hh = parseInt(ampm[1], 10);
    const mm = (ampm[2] || '0').padStart(2, '0');
    if (ampm[3].toLowerCase() === 'pm' && hh < 12) hh += 12;
    if (ampm[3].toLowerCase() === 'am' && hh === 12) hh = 0;
    return hh.toString().padStart(2, '0') + ':' + mm;
  }

  if (/^\d{1,2}$/.test(v)) {
    let hh = parseInt(v, 10);
    if (hh >= 1 && hh <= 8) hh += 12;
    return hh.toString().padStart(2, '0') + ':00';
  }
  if (/^\d{1,2}:\d{1,2}:\d{1,2}$/.test(v)) v = v.split(':').slice(0, 2).join(':');
  if (/^\d{1,2}:\d{1,2}$/.test(v)) {
    const parts = v.split(':');
    return parts[0].padStart(2, '0') + ':' + parts[1].padStart(2, '0');
  }

  return v;
};

const horaEnMinutos = horaStr => {
  const m = (horaStr || '').match(/^(\d{2}):(\d{2})$/);
  if (!m) return null;
  const hh = parseInt(m[1], 10);
  const mm = parseInt(m[2], 10);
  if (hh < 0 || hh > 23 || mm < 0 || mm > 59) return null;
  return hh * 60 + mm;
};

const sumarMinutos = (horaStr, minutos) => {
  const inicio = horaEnMinutos(horaStr);
  if (inicio === null) return '';
  const total = inicio + minutos;
  const hh = Math.floor(total / 60).toString().padStart(2, '0');
  const mm = (total % 60).toString().padStart(2, '0');
  return hh + ':' + mm;
};

const fechaISOValida = fechaStr => {
  if (!/^\d{4}-\d{2}-\d{2}$/.test(fechaStr || '')) return false;
  const parts = fechaStr.split('-').map(Number);
  const d = new Date(Date.UTC(parts[0], parts[1] - 1, parts[2]));
  return d.getUTCFullYear() === parts[0] && d.getUTCMonth() === parts[1] - 1 && d.getUTCDate() === parts[2];
};

const obtenerDiaSemana = fechaStr => {
  if (!fechaISOValida(fechaStr)) return -1;
  const parts = fechaStr.split('-').map(Number);
  return new Date(Date.UTC(parts[0], parts[1] - 1, parts[2])).getUTCDay();
};

const hoyClinica = () => {
  const parts = new Intl.DateTimeFormat('en-US', {
    timeZone: TIME_ZONE,
    year: 'numeric',
    month: '2-digit',
    day: '2-digit'
  }).formatToParts(new Date());
  const get = type => parts.find(p => p.type === type).value;
  return get('year') + '-' + get('month') + '-' + get('day');
};

const fechaClinicaMasDias = dias => {
  const base = hoyClinica().split('-').map(Number);
  const d = new Date(Date.UTC(base[0], base[1] - 1, base[2] + dias));
  return d.getUTCFullYear() + '-' + (d.getUTCMonth() + 1).toString().padStart(2, '0') + '-' + d.getUTCDate().toString().padStart(2, '0');
};

const normalizarFechaEntrada = valor => {
  const raw = (valor || '').toString().trim();
  if (!raw) return '';
  const texto = normalizarTexto(raw);

  if (/\b(pasado manana|pasado ma?ana|after tomorrow|depois de amanha|depois de amanh?)\b/.test(texto)) {
    return fechaClinicaMasDias(2);
  }
  if (/\b(manana|ma?ana|tomorrow|amanha|amanh?)\b/.test(texto)) {
    return fechaClinicaMasDias(1);
  }
  if (/\b(hoy|today|hoje)\b/.test(texto)) {
    return hoyClinica();
  }

  const iso = raw.match(/(\d{4})[-\/](\d{1,2})[-\/](\d{1,2})/);
  if (iso) {
    const fecha = iso[1] + '-' + iso[2].padStart(2, '0') + '-' + iso[3].padStart(2, '0');
    return fechaISOValida(fecha) ? fecha : '';
  }

  const europeo = raw.match(/(\d{1,2})[\/.-](\d{1,2})[\/.-](\d{4})/);
  if (europeo) {
    const fecha = europeo[3] + '-' + europeo[2].padStart(2, '0') + '-' + europeo[1].padStart(2, '0');
    return fechaISOValida(fecha) ? fecha : '';
  }

  const meses = {
    january: 1, jan: 1, enero: 1, janeiro: 1, janvier: 1,
    february: 2, feb: 2, febrero: 2, fevereiro: 2, fevrier: 2, fevrier: 2,
    march: 3, mar: 3, marzo: 3, marco: 3, mars: 3,
    april: 4, apr: 4, abril: 4, avril: 4,
    may: 5, mayo: 5, maio: 5, mai: 5,
    june: 6, jun: 6, junio: 6, junho: 6, juin: 6,
    july: 7, jul: 7, julio: 7, julho: 7, juillet: 7,
    august: 8, aug: 8, agosto: 8, aout: 8,
    september: 9, sep: 9, septiembre: 9, setembro: 9, septembre: 9,
    october: 10, oct: 10, octubre: 10, outubro: 10, octobre: 10,
    november: 11, nov: 11, noviembre: 11, novembro: 11, novembre: 11,
    december: 12, dec: 12, diciembre: 12, dezembro: 12, decembre: 12
  };
  const monthName = Object.keys(meses).find(mes => new RegExp('\\b' + mes + '\\b').test(texto));
  if (monthName) {
    const yearMatch = raw.match(/(20\d{2})/);
    const sinYear = raw.replace(/20\d{2}/g, ' ');
    const dayMatches = [...sinYear.matchAll(/\b(\d{1,2})\b/g)].map(match => Number(match[1])).filter(n => n >= 1 && n <= 31);
    const day = dayMatches[dayMatches.length - 1];
    const year = yearMatch ? Number(yearMatch[1]) : Number(hoyClinica().slice(0, 4));
    if (day) {
      const fecha = year + '-' + meses[monthName].toString().padStart(2, '0') + '-' + day.toString().padStart(2, '0');
      return fechaISOValida(fecha) ? fecha : '';
    }
  }

  return '';
};

const normalizarFechasAccion = (data, accion) => {
  for (const campo of ['fecha', 'fecha_actual', 'fecha_nueva']) {
    const fecha = normalizarFechaEntrada(data[campo]);
    if (fecha) data[campo] = fecha;
  }

  const fechaMensaje = normalizarFechaEntrada(mensajeActual);
  if (fechaMensaje) {
    if ((accion === 'reservar' || accion === 'consultar_horarios' || accion === 'cancelar') && datoVacio(data.fecha)) {
      data.fecha = fechaMensaje;
    }
    if (accion === 'modificar' && datoVacio(data.fecha_nueva)) {
      data.fecha_nueva = fechaMensaje;
    }
  }
};

const validarFechaFutura = fechaStr => fechaISOValida(fechaStr) && fechaStr >= hoyClinica();

const horarioDia = fechaStr => {
  const dia = obtenerDiaSemana(fechaStr);
  if (dia === -1) return null;
  return CFG.horarios[dia] || null;
};

const validarHorario = (fechaStr, horaStr, duracionMin = DURACION_CITA_MIN) => {
  const horario = horarioDia(fechaStr);
  const inicio = horaEnMinutos(horaStr);
  if (!horario || inicio === null) return false;
  const apertura = horaEnMinutos(horario.apertura);
  const cierre = horaEnMinutos(horario.cierre);
  if (apertura === null || cierre === null) return false;
  return inicio >= apertura && inicio + duracionMin <= cierre;
};

// Una cita solo cabe si TERMINA antes de cerrar. Con cierre a las 20:00 y una
// limpieza de 45 min, la ultima hora a la que se puede empezar es 19:15.
const ultimaHoraInicio = (fechaStr, duracionMin) => {
  const horario = horarioDia(fechaStr);
  if (!horario) return '';
  const apertura = horaEnMinutos(horario.apertura);
  const cierre = horaEnMinutos(horario.cierre);
  if (apertura === null || cierre === null) return '';
  const ultima = cierre - duracionMin;
  if (ultima < apertura) return '';
  return Math.floor(ultima / 60).toString().padStart(2, '0') + ':' + (ultima % 60).toString().padStart(2, '0');
};

// Explica POR QUE no cabe, en vez de soltar el horario y dejar al paciente
// pensando que las 20:00 valen porque "abrimos hasta las 20:00".
const mensajeFueraDeHorario = (fechaStr, duracionMin) => {
  const horario = horarioDia(fechaStr);
  if (!horario) {
    return 'Ese día la clínica está cerrada. Nuestro horario es: ' + CFG.horarioTexto + '. ¿Te viene bien otro día?';
  }
  const ultima = ultimaHoraInicio(fechaStr, duracionMin);
  if (ultima) {
    return 'Esa hora no me cuadra: ese día atendemos de ' + horario.apertura + ' a ' + horario.cierre
      + ', y la cita dura ' + duracionMin + ' minutos, así que la última que puedo darte empieza a las '
      + ultima + '. ¿Te viene bien esa u otra antes?';
  }
  return 'Esa hora queda fuera de nuestro horario. Nuestro horario es: ' + CFG.horarioTexto + '. ¿Qué otra hora te vendría bien?';
};

const offsetClinica = (fechaStr, horaStr) => {
  const probe = new Date(fechaStr + 'T' + horaStr + ':00Z');
  const parts = new Intl.DateTimeFormat('en-US', {
    timeZone: TIME_ZONE,
    hour: '2-digit',
    minute: '2-digit',
    timeZoneName: 'longOffset'
  }).formatToParts(probe);
  const tz = (parts.find(p => p.type === 'timeZoneName') || {}).value || 'GMT+00:00';
  const m = tz.match(/GMT([+-])(\d{1,2})(?::?(\d{2}))?/);
  if (!m) return '+00:00';
  return m[1] + m[2].padStart(2, '0') + ':' + (m[3] || '00').padStart(2, '0');
};

const isoClinica = (fechaStr, horaStr) => fechaStr + 'T' + horaStr + ':00' + offsetClinica(fechaStr, horaStr);

const fechaHoraFutura = (fechaStr, horaStr) => {
  if (!fechaISOValida(fechaStr) || horaEnMinutos(horaStr) === null) return false;
  const fechaHora = new Date(isoClinica(fechaStr, horaStr));
  return !Number.isNaN(fechaHora.getTime()) && fechaHora.getTime() > Date.now();
};

const extraerTratamientoMensaje = texto => {
  const valor = normalizarTexto(texto);
  const encontrado = DURACIONES_TRATAMIENTO.find(item =>
    item.patrones.some(patron => valor.includes(normalizarTexto(patron)))
  );
  return encontrado ? encontrado.nombre : '';
};

const extraerHoraMensaje = texto => {
  const raw = (texto || '').toString().replace(/\s+/g, ' ').trim();
  const patrones = [
    /\b(?:a\s+)?(?:las?|los)\s+(\d{1,2})(?::(\d{1,2}))?\s*(am|pm)?\b/i,
    /\b(\d{1,2}):(\d{1,2})\s*(am|pm)?\b/i
  ];
  for (const patron of patrones) {
    const match = raw.match(patron);
    if (!match) continue;
    const valor = match[1] + (match[2] ? ':' + match[2] : '') + (match[3] ? ' ' + match[3] : '');
    const hora = normHora(valor);
    if (horaEnMinutos(hora) !== null) return hora;
  }
  return '';
};

const esSolicitudReservaAdministrativa = texto => /\b(cita|reservar|reserva|agendar|pedir hora|quiero|quisiera|necesito|appointment|marcar consulta)\b/.test(normalizarTexto(texto));

const esConsultaCitaExistente = texto => {
  const valor = normalizarTexto(texto);
  if (!valor || contieneInfoClinicaPrivada(texto)) return false;
  if (/\b(cancelar|cambiar|modificar|mover|reprogramar|reservar|agendar|pedir hora|horarios?|disponibilidad|huecos?|agenda)\b/.test(valor)) return false;
  const mencionaCita = /\b(mi cita|mis citas|mi reserva|mis reservas|cita que tengo|cita pendiente|cita reservada|cuando tengo cita|cuando tenia cita|cuando era mi cita|cuando es mi cita|cuando toca|cuando me toca|appointment|my appointment)\b/.test(valor)
    || (/\bcita\b/.test(valor) && /\b(cuando|fecha|hora|dia|recordar|recuerdame|saber|consultar|confirmar|ver|buscar|tengo|tenia)\b/.test(valor));
  const mencionaTratamientoYaReservado = contieneTratamiento(valor)
    && /\b(tenia|tengo|reserve|reservado|reservada|no se cuando|no recuerdo|cuando fue|cuando era|cuando es)\b/.test(valor);
  return mencionaCita || mencionaTratamientoYaReservado;
};

const EXTRAS_COMERCIALES = ['implante', 'implantes', 'carillas', 'invisalign'];
const contieneServicioComercialLead = texto => {
  const valor = normalizarTexto(texto);
  return DURACIONES_TRATAMIENTO.some(item => item.patrones.some(p => valor.includes(normalizarTexto(p))))
    || EXTRAS_COMERCIALES.some(p => valor.includes(p));
};

const esConsultaComercialLead = texto => {
  const valor = normalizarTexto(texto);
  if (!valor || contieneInfoClinicaPrivada(texto) || esConsultaCitaExistente(texto)) return false;
  if (/\b(cancelar|cambiar|modificar|mover|reprogramar|reservar|reserva|cita|agendar|pedir hora|horarios?|disponibilidad|huecos?|agenda)\b/.test(valor)) return false;
  if (/\b(servicios?|que ofrecen|que tratamientos tienen|que servicios tienen|direccion|telefono|horario)\b/.test(valor) && !contieneServicioComercialLead(valor)) return false;
  return contieneServicioComercialLead(valor)
    && /\b(precio|precios|cuanto cuesta|coste|costos|presupuesto|financiacion|financiado|informacion|info|me interesa|interesado|interesada|quiero saber|llamadme|llamarme|contactarme|consulta comercial|ortodoncia|blanqueamiento|limpieza|empaste|revision|implante|implantes|carillas|invisalign)\b/.test(valor);
