const esConsultaServiciosGeneral = texto => {
  const valor = normalizarTexto(texto);
  if (!valor || contieneInfoClinicaPrivada(texto)) return false;
  if (/\b(precio|precios|cuanto cuesta|coste|costos|presupuesto|financiacion|financiado|reservar|reserva|cita|agendar|pedir hora|horarios?|disponibilidad|huecos?|agenda)\b/.test(valor)) return false;
