  .toLowerCase()
  .normalize('NFD')
  .replace(/[\u0300-\u036f]/g, '')
  .replace(/\s+/g, ' ')
  .trim();
const normalizarTelefono = v => (v || '').toString().replace(/\D/g, '');
const telefonosCompatibles = (a, b) => {
  const x = normalizarTelefono(a);
  const y = normalizarTelefono(b);
  if (!x || !y) return false;
  return x === y || (x.length >= 9 && y.length >= 9 && x.slice(-9) === y.slice(-9));
};

const nombresCompatibles = (a, b) => {
  const x = normalizarTexto(a);
  const y = normalizarTexto(b);
  if (!x || !y) return false;
  if (x === y) return true;
  // "Luis" tiene que encontrar la cita de "Luis Ander": basta con que todas
  // las palabras del nombre mas corto aparezcan en el mas largo.
  const pa = x.split(' ').filter(Boolean);
  const pb = y.split(' ').filter(Boolean);
  const corto = pa.length <= pb.length ? pa : pb;
  const largo = pa.length <= pb.length ? pb : pa;
  return corto.length > 0 && corto.every(p => largo.includes(p));
};
