const CFG = $('Construir contexto').first().json.config;
const TIME_ZONE = CFG.zona_horaria;

const datos = $('Normalizar y enrutar').first().json;
const fecha = datos.fecha;
const duracion = Number(datos.duracion_minutos) || 60;
const pasoMinutos = 30;

const horaEnMinutos = horaStr => {
  const m = (horaStr || '').match(/^(\d{2}):(\d{2})$/);
  if (!m) return null;
  return parseInt(m[1], 10) * 60 + parseInt(m[2], 10);
};

const formatoHora = minutos => {
  const hh = Math.floor(minutos / 60).toString().padStart(2, '0');
  const mm = (minutos % 60).toString().padStart(2, '0');
  return hh + ':' + mm;
};

const hoyClinica = () => {
  const parts = new Intl.DateTimeFormat('en-US', {
    timeZone: TIME_ZONE,
    year: 'numeric',
    month: '2-digit',
    day: '2-digit'
  }).formatToParts(new Date());
  const get = type => parts.find(p => p.type === type).value;
  return get('year') + '-' + get('month') + '-' + get('day');
};

const offsetClinica = (fechaStr, horaStr) => {
  const probe = new Date(fechaStr + 'T' + horaStr + ':00Z');
  const parts = new Intl.DateTimeFormat('en-US', {
    timeZone: TIME_ZONE,
    hour: '2-digit',
    minute: '2-digit',
    timeZoneName: 'longOffset'
  }).formatToParts(probe);
  const tz = (parts.find(p => p.type === 'timeZoneName') || {}).value || 'GMT+00:00';
  const m = tz.match(/GMT([+-])(\d{1,2})(?::?(\d{2}))?/);
  if (!m) return '+00:00';
  return m[1] + m[2].padStart(2, '0') + ':' + (m[3] || '00').padStart(2, '0');
};

const isoClinica = (fechaStr, horaStr) => fechaStr + 'T' + horaStr + ':00' + offsetClinica(fechaStr, horaStr);

const eventos = $input.all()
  .map(item => item.json || {})
  .filter(evento => evento.status !== 'cancelled' && (evento.start?.dateTime || evento.start?.date))
  .map(evento => {
    const startRaw = evento.start?.dateTime || isoClinica(evento.start.date, '00:00');
    const endRaw = evento.end?.dateTime || isoClinica(evento.end.date, '00:00');
    return {
      start: new Date(startRaw),
      end: new Date(endRaw)
    };
  })
  .filter(evento => !Number.isNaN(evento.start.getTime()) && !Number.isNaN(evento.end.getTime()));

const apertura = horaEnMinutos(datos.hora_apertura);
const cierre = horaEnMinutos(datos.hora_cierre);
const libres = [];
const ahora = new Date();

for (let inicioMin = apertura; inicioMin + duracion <= cierre; inicioMin += pasoMinutos) {
  const horaInicio = formatoHora(inicioMin);
  const horaFin = formatoHora(inicioMin + duracion);
  const slotInicio = new Date(isoClinica(fecha, horaInicio));
  const slotFin = new Date(isoClinica(fecha, horaFin));
  if (fecha === hoyClinica() && slotInicio <= ahora) continue;
  const ocupado = eventos.some(evento => slotInicio < evento.end && slotFin > evento.start);
  if (!ocupado) libres.push(horaInicio);
}

const fechaES = fecha.split('-').reverse().join('/');
const tratamiento = datos.tratamiento || 'cita estándar';
let respuesta;

if (!libres.length) {
  respuesta = fecha === hoyClinica()
    ? 'Para hoy ya no veo huecos libres para ' + tratamiento + '. ¿Quieres que mire otro día?'
    : 'Lo siento, no veo huecos libres el ' + fechaES + ' para ' + tratamiento + '. ¿Qué otro día te vendría bien?';
} else {
  const agruparHoras = horas => {
    const grupos = [];
    for (let i = 0; i < horas.length; i += 4) {
      grupos.push(horas.slice(i, i + 4).join(', '));
    }
    return grupos.join('\n');
  };
  const manana = libres.filter(hora => hora < '14:00');
  const tarde = libres.filter(hora => hora >= '14:00');
  const lineas = [];
